{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "CP-331,684, the closest retrieved analogue (a phenylethanolamine with an aromatic amino group), had 27% absolute oral bioavailability in humans, directly supporting F≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Labetalol, a phenylethanolamine beta-blocker with an amide and aromatic hydroxyl, had absolute oral bioavailability of 28% (19–49%) in humans, with multiple studies clustering at 20–44%, supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Bevantolol, a related phenylethanolamine/aryloxypropanolamine beta-blocker, had mean absolute bioavailability of 57% in healthy volunteers, supporting high oral availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Epanolol, which shares the Ar-CH(OH)-CH2-NH-CH2CH2-NH-CO-CH2-Ar scaffold, had only 7.06±3.15% oral bioavailability in humans; this is the strongest low-F counter-evidence, but its phenolic OH and cyanophenoxy ether are metabolic liabilities absent in the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "Salmeterol, a phenylethanolamine, had ~1% oral bioavailability, but its very long lipophilic substituent and different polar architecture limit transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a phenylethanolamine with an amide-ethylenediamine linker. The closest and most numerous transferable human F measurements (CP-331,684 27%, labetalol 20–44%, bevantolol 57%) support F≥20%. Epanolol's low F is structurally relevant, but its phenol/cyanophenoxy first-pass liabilities are absent in the query, so the low evidence is outweighed. Prediction: high.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule.",
    "Morgan similarities are all below 0.35, limiting quantitative transfer.",
    "No metabolic stability or first-pass clearance data for the query's aminothiazole-acetamide moiety.",
    "Epanolol's low F cannot be fully deconvoluted from its phenolic/cyanophenoxy groups."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

